-- Nestora · Phase 1
-- Storefront: universities, listings, favorites, visit requests (P04 → P13).
-- Backoffice: staff roles, email 2FA, sessions, audit log, command center (AP1A_01 → AP1A_18).
--
-- Email OTP codes for students are generated and emailed by Supabase Auth
-- (see supabase/config.toml and supabase/templates). Staff 2FA codes are
-- generated by the backoffice server and only their hash is stored here.

-- ---------------------------------------------------------------------------
-- 0. Retire the demo phone OTP table (hard-coded 000000 code).
-- ---------------------------------------------------------------------------
drop table if exists public.otp_verifications;

-- ---------------------------------------------------------------------------
-- 1. Reference data
-- ---------------------------------------------------------------------------
