-- ---------------------------------------------------------------------------
-- 2. Listings (P05 → P10)
-- ---------------------------------------------------------------------------
create type public.listing_type as enum ('s0', 's1', 's2', 's3', 'private_room', 'private_foyer');
create type public.listing_status as enum ('draft', 'published', 'rented', 'archived');
create type public.nearby_kind as enum ('university', 'transport', 'cafe', 'supermarket');

create table public.listings (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title text not null,
  short_title text not null,
  headline text not null,
  tagline text not null default '',
  description text not null default '',
  listing_type public.listing_type not null,
  university_id text references public.universities(id) on delete set null,
  neighborhood text not null,
  city text not null default 'Tunis',
  maps_url text,
  price_tnd integer not null check (price_tnd > 0),
  service_included boolean not null default true,
  walk_minutes integer not null default 10 check (walk_minutes >= 0),
  capacity smallint not null default 1 check (capacity > 0),
  available_places smallint not null default 1 check (available_places >= 0),
  hold_slots_total smallint not null default 3,
  hold_slots_available smallint not null default 3,
  available_from date not null,
  status public.listing_status not null default 'draft',
  verified_onsite boolean not null default false,
  address_verified boolean not null default false,
  photos_verified boolean not null default false,
  landlord_verified boolean not null default false,
  confidence_score smallint check (confidence_score between 0 and 100),
  is_furnished boolean not null default false,
  in_residence boolean not null default false,
  has_wifi boolean not null default false,
  has_ac boolean not null default false,
  has_heating boolean not null default false,
  has_desk boolean not null default false,
  deposit_label text not null default '1 mois de loyer',
  charges_label text not null default 'Eau et électricité non incluses',
  visits_label text not null default 'Sur demande et confirmation',
  collections text[] not null default '{}',
  availability_confirmed_at timestamptz,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index listings_search_idx on public.listings (status, university_id, available_from, price_tnd);
create index listings_collections_idx on public.listings using gin (collections);

create table public.listing_photos (
  id uuid primary key default gen_random_uuid(),
  listing_id uuid not null references public.listings(id) on delete cascade,
  url text not null,
  alt text not null default '',
  position text not null default 'center',
  sort_order smallint not null default 0
);

create index listing_photos_listing_idx on public.listing_photos (listing_id, sort_order);

create table public.listing_nearby (
  id uuid primary key default gen_random_uuid(),
  listing_id uuid not null references public.listings(id) on delete cascade,
  kind public.nearby_kind not null,
  minutes smallint not null check (minutes >= 0),
  unique (listing_id, kind)
);

create trigger listings_set_updated_at
before update on public.listings
for each row execute function public.set_updated_at();

create table public.favorites (
  user_id uuid not null references auth.users(id) on delete cascade,
  listing_id uuid not null references public.listings(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, listing_id)
);

-- ---------------------------------------------------------------------------
-- 3. Visit requests (P12 → P13)
-- ---------------------------------------------------------------------------
create type public.visit_status as enum ('requested', 'slot_confirmation', 'confirmed', 'cancelled', 'completed');

create table public.visit_requests (
  id uuid primary key default gen_random_uuid(),
  reference text not null unique default 'VIS-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6)),
  listing_id uuid not null references public.listings(id) on delete cascade,
  student_id uuid not null references auth.users(id) on delete cascade,
  preferred_dates date[] not null,
  slot_start time not null,
  slot_end time not null,
  status public.visit_status not null default 'requested',
  confirmed_at timestamptz,
  confirmed_date date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint visit_three_dates check (cardinality(preferred_dates) = 3),
  constraint visit_slot_order check (slot_end > slot_start)
);

create index visit_requests_student_idx on public.visit_requests (student_id, status);
create index visit_requests_listing_idx on public.visit_requests (listing_id, status);

create or replace function public.validate_visit_request()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  active_count integer;
begin
  if (select count(distinct d) from unnest(new.preferred_dates) as d) <> 3 then
    raise exception 'Choisis trois dates différentes.' using errcode = 'check_violation';
  end if;

  if exists (select 1 from unnest(new.preferred_dates) as d where d < current_date) then
    raise exception 'Les dates doivent être dans le futur.' using errcode = 'check_violation';
  end if;

  if not exists (select 1 from public.listings where id = new.listing_id and status = 'published') then
    raise exception 'Ce logement n''est plus disponible.' using errcode = 'check_violation';
  end if;

  if tg_op = 'INSERT' then
    select count(*) into active_count
    from public.visit_requests
    where student_id = new.student_id
      and status in ('requested', 'slot_confirmation', 'confirmed');

    if active_count >= 3 then
      raise exception 'Tu as déjà trois visites actives.' using errcode = 'check_violation';
    end if;
  end if;

  return new;
end;
$$;

create trigger visit_requests_validate
before insert or update of preferred_dates, listing_id on public.visit_requests
for each row execute function public.validate_visit_request();

create trigger visit_requests_set_updated_at
before update on public.visit_requests
for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 4. Operations records used by the Command Center
