create type public.rental_case_status as enum ('open', 'payment_review', 'contract', 'move_in', 'closed', 'cancelled');
create type public.hold_status as enum ('active', 'released', 'expired', 'converted');
create type public.payment_status as enum ('submitted', 'reconciled', 'rejected');

create table public.rental_cases (
  id uuid primary key default gen_random_uuid(),
  reference text not null unique,
  listing_id uuid references public.listings(id) on delete set null,
  student_id uuid references auth.users(id) on delete set null,
  student_name text not null,
  status public.rental_case_status not null default 'open',
  needs_action boolean not null default false,
  is_complete boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.holds (
  id uuid primary key default gen_random_uuid(),
  listing_id uuid not null references public.listings(id) on delete cascade,
  student_id uuid references auth.users(id) on delete set null,
  student_name text not null,
  status public.hold_status not null default 'active',
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);

create table public.payments (
  id uuid primary key default gen_random_uuid(),
  reference text not null unique,
  rental_case_id uuid references public.rental_cases(id) on delete set null,
  amount_tnd integer not null check (amount_tnd > 0),
  status public.payment_status not null default 'submitted',
  submitted_at timestamptz not null default now(),
  reconciled_at timestamptz
);

