-- Six-digit codes are hashed with a server-side secret (ADMIN_2FA_SECRET) before storage.
create table public.staff_mfa_challenges (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  auth_session_id uuid not null,
  code_hash text not null,
  attempts smallint not null default 0,
  expires_at timestamptz not null,
  consumed_at timestamptz,
  created_at timestamptz not null default now()
);

create index staff_mfa_challenges_lookup_idx on public.staff_mfa_challenges (user_id, auth_session_id, created_at desc);

-- One row per Supabase Auth session that passed 2FA.
create table public.staff_sessions (
  auth_session_id uuid primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  mfa_verified_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  remember_device boolean not null default false,
  ip_address text,
  user_agent text,
  revoked_at timestamptz,
  revoked_reason text,
  created_at timestamptz not null default now()
);

create index staff_sessions_user_idx on public.staff_sessions (user_id, created_at desc);

create table public.audit_log (
  id bigint generated always as identity primary key,
  actor_id uuid references auth.users(id) on delete set null,
  action text not null,
  resource text,
  metadata jsonb not null default '{}',
  ip_address text,
  user_agent text,
  created_at timestamptz not null default now()
);

create index audit_log_actor_idx on public.audit_log (actor_id, created_at desc);
create index audit_log_action_idx on public.audit_log (action, created_at desc);

-- Work items shown in "À traiter maintenant" and "Ma priorité maintenant".
create type public.ops_task_kind as enum ('payment', 'visit', 'contract', 'hold', 'availability', 'follow_up');
create type public.ops_tone as enum ('warning', 'info', 'success', 'danger', 'neutral');

create table public.ops_tasks (
  id uuid primary key default gen_random_uuid(),
  kind public.ops_task_kind not null,
  title text not null,
  detail text not null default '',
  status_label text not null,
  tone public.ops_tone not null default 'neutral',
  action_label text not null default 'Ouvrir',
  is_approval boolean not null default false,
  initials text not null default '',
  priority smallint not null default 50,
  assignee_id uuid references auth.users(id) on delete set null,
  due_at timestamptz,
  completed_at timestamptz,
  reopened_count smallint not null default 0,
  created_at timestamptz not null default now()
);

create index ops_tasks_open_idx on public.ops_tasks (completed_at, priority desc, due_at);
create index ops_tasks_assignee_idx on public.ops_tasks (assignee_id, completed_at);

create table public.ops_schedule_events (
  id uuid primary key default gen_random_uuid(),
  starts_at timestamptz not null,
  title text not null,
  detail text not null default '',
  tone public.ops_tone not null default 'neutral',
  assignee_id uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);

create index ops_schedule_events_day_idx on public.ops_schedule_events (starts_at);

-- ---------------------------------------------------------------------------
-- 6. Staff helpers (used by RLS and RPCs)
-- ---------------------------------------------------------------------------
create or replace function public.staff_idle_minutes()
returns integer
language sql
immutable
as $$ select 20 $$;

-- True when the caller is an active staff member whose current Auth session passed 2FA
-- and has not been idle for more than 20 minutes.
create or replace function public.is_verified_staff()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.staff_members m
    join public.staff_sessions s on s.user_id = m.user_id
    where m.user_id = auth.uid()
      and m.is_active
      and s.auth_session_id = nullif(auth.jwt() ->> 'session_id', '')::uuid
      and s.revoked_at is null
      and s.last_seen_at > now() - make_interval(mins => public.staff_idle_minutes())
  );
$$;

create or replace function public.staff_has_permission(required text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.is_verified_staff() and exists (
    select 1
    from public.staff_members m
    join public.staff_role_permissions p on p.role = m.role
    where m.user_id = auth.uid() and p.permission = required
  );
$$;

-- ---------------------------------------------------------------------------
-- 7. Dashboard RPCs
-- ---------------------------------------------------------------------------
create or replace function public.ops_command_center_stats()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result jsonb;
  tz text := 'Africa/Tunis';
  today date := (now() at time zone tz)::date;
begin
  if not public.staff_has_permission('command_center.view') then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'published_listings', (select count(*) from listings where status = 'published'),
    'published_this_week', (select count(*) from listings where status = 'published' and published_at > now() - interval '7 days'),
    'available_places', (select coalesce(sum(available_places), 0) from listings where status = 'published'),
    'availability_fresh_pct', (
      select coalesce(round(100.0 * count(*) filter (where availability_confirmed_at > now() - interval '7 days') / nullif(count(*), 0)), 0)
      from listings where status = 'published'),
    'active_cases', (select count(*) from rental_cases where status not in ('closed', 'cancelled')),
    'cases_need_action', (select count(*) from rental_cases where status not in ('closed', 'cancelled') and needs_action),
    'cases_complete_pct', (
      select coalesce(round(100.0 * count(*) filter (where is_complete) / nullif(count(*), 0)), 0)
      from rental_cases where status not in ('cancelled')),
    'visits_today', (
      select count(*) from visit_requests
      where status = 'confirmed' and confirmed_date = today),
    'visits_to_confirm', (select count(*) from visit_requests where status in ('requested', 'slot_confirmation')),
    'holds_under_3h', (
      select count(*) from holds
      where status = 'active' and expires_at between now() and now() + interval '3 hours'),
    'holds_at_risk', (
      select count(*) from holds
      where status = 'active' and expires_at between now() and now() + interval '1 hour'),
    'payments_to_verify', (select count(*) from payments where status = 'submitted'),
    'oldest_payment_minutes', (
      select coalesce(floor(extract(epoch from now() - min(submitted_at)) / 60), 0)::int
      from payments where status = 'submitted'),
    'payments_reconciled_pct', (
      select coalesce(round(100.0 * count(*) filter (where status = 'reconciled') / nullif(count(*), 0)), 0)
      from payments where submitted_at > now() - interval '30 days'),
    'sla_pct', (
      select coalesce(round(100.0 * count(*) filter (where due_at is null or completed_at <= due_at) / nullif(count(*), 0)), 0)
      from ops_tasks where completed_at > now() - interval '30 days'),
    'open_tasks', (select count(*) from ops_tasks where completed_at is null)
  ) into result;

  return result;
end;
$$;

create or replace function public.ops_workspace_stats()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  me uuid := auth.uid();
  tz text := 'Africa/Tunis';
  today date := (now() at time zone tz)::date;
begin
  if not public.staff_has_permission('workspace.view') then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'open_tasks', (select count(*) from ops_tasks where assignee_id = me and completed_at is null),
    'due_before_13', (
      select count(*) from ops_tasks
      where assignee_id = me and completed_at is null
        and due_at <= ((today + time '13:00') at time zone tz)),
    'approvals', (select count(*) from ops_tasks where assignee_id = me and completed_at is null and is_approval),
    'sensitive_payments', (
      select count(*) from ops_tasks
      where assignee_id = me and completed_at is null and is_approval and kind = 'payment'),
    'planning_today', (
      select count(*) from ops_schedule_events
      where assignee_id = me and (starts_at at time zone tz)::date = today),
    'next_event_at', (
      select min(starts_at) from ops_schedule_events
      where assignee_id = me and starts_at >= now()),
    'at_risk', (
      select count(*) from ops_tasks
      where assignee_id = me and completed_at is null and due_at < now() + interval '1 hour'),
    'oldest_at_risk_minutes', (
      select coalesce(floor(extract(epoch from now() - min(created_at)) / 60), 0)::int
      from ops_tasks
      where assignee_id = me and completed_at is null and due_at < now() + interval '1 hour'),
    'in_time_pct', (
      select coalesce(round(100.0 * count(*) filter (where due_at is null or completed_at <= due_at) / nullif(count(*), 0)), 0)
      from ops_tasks where assignee_id = me and completed_at > now() - interval '30 days'),
    'median_minutes', (
      select coalesce(round(percentile_cont(0.5) within group (order by extract(epoch from completed_at - created_at) / 60)), 0)
      from ops_tasks where assignee_id = me and completed_at > now() - interval '30 days'),
    'reopened', (
      select coalesce(sum(reopened_count), 0) from ops_tasks
      where assignee_id = me and created_at > now() - interval '30 days')
  );
end;
$$;

revoke execute on function public.ops_command_center_stats() from public, anon;
revoke execute on function public.ops_workspace_stats() from public, anon;
grant execute on function public.ops_command_center_stats() to authenticated;
grant execute on function public.ops_workspace_stats() to authenticated;

-- ---------------------------------------------------------------------------
-- 8. Row level security
-- ---------------------------------------------------------------------------
alter table public.universities enable row level security;
alter table public.listings enable row level security;
alter table public.listing_photos enable row level security;
alter table public.listing_nearby enable row level security;
alter table public.favorites enable row level security;
alter table public.visit_requests enable row level security;
alter table public.rental_cases enable row level security;
alter table public.holds enable row level security;
alter table public.payments enable row level security;
alter table public.staff_members enable row level security;
alter table public.staff_role_permissions enable row level security;
alter table public.staff_mfa_challenges enable row level security;
alter table public.staff_sessions enable row level security;
alter table public.audit_log enable row level security;
alter table public.ops_tasks enable row level security;
alter table public.ops_schedule_events enable row level security;

-- Public catalogue
create policy "Anyone can read active universities" on public.universities
for select to anon, authenticated using (is_active or public.is_verified_staff());

create policy "Anyone can read published listings" on public.listings
for select to anon, authenticated using (status = 'published' or public.staff_has_permission('properties.view'));

create policy "Anyone can read photos of published listings" on public.listing_photos
for select to anon, authenticated using (
  exists (select 1 from public.listings l where l.id = listing_id and (l.status = 'published' or public.is_verified_staff())));

create policy "Anyone can read surroundings of published listings" on public.listing_nearby
for select to anon, authenticated using (
  exists (select 1 from public.listings l where l.id = listing_id and (l.status = 'published' or public.is_verified_staff())));

-- Students
create policy "Students manage own favorites" on public.favorites
for all to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);

create policy "Students read own visit requests" on public.visit_requests
for select to authenticated using (auth.uid() = student_id or public.staff_has_permission('visits.view'));

create policy "Students create own visit requests" on public.visit_requests
for insert to authenticated with check (auth.uid() = student_id and status = 'requested');

create policy "Staff update visit requests" on public.visit_requests
for update to authenticated using (public.staff_has_permission('visits.view'))
with check (public.staff_has_permission('visits.view'));

-- Operations
create policy "Staff read rental cases" on public.rental_cases
for select to authenticated using (public.staff_has_permission('reservations.view') or public.staff_has_permission('contracts.view'));

create policy "Staff read holds" on public.holds
for select to authenticated using (public.staff_has_permission('holds.view'));

create policy "Staff read payments" on public.payments
for select to authenticated using (public.staff_has_permission('payments.view'));

create policy "Staff read own membership" on public.staff_members
for select to authenticated using (auth.uid() = user_id or public.staff_has_permission('team.manage'));

create policy "Staff read role permissions" on public.staff_role_permissions
for select to authenticated using (
  exists (select 1 from public.staff_members m where m.user_id = auth.uid() and m.is_active));

create policy "Staff read audit log" on public.audit_log
for select to authenticated using (public.staff_has_permission('audit.view'));

create policy "Staff read tasks" on public.ops_tasks
for select to authenticated using (public.is_verified_staff());

create policy "Staff update tasks" on public.ops_tasks
for update to authenticated using (public.is_verified_staff()) with check (public.is_verified_staff());

create policy "Staff read schedule" on public.ops_schedule_events
for select to authenticated using (public.is_verified_staff());

-- staff_mfa_challenges and staff_sessions have no policies on purpose:
-- only the backoffice server (service role) can read or write them.

-- ---------------------------------------------------------------------------
-- 9. Student profile sync after email OTP sign-up
-- ---------------------------------------------------------------------------
create or replace function public.create_student_profile_for_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Staff accounts are created by an administrator and never get a student profile.
  if coalesce(new.raw_app_meta_data ->> 'account_type', '') = 'staff' then
    return new;
  end if;

  insert into public.student_profiles (
    user_id, email, first_name, last_name, phone_country_code, phone_number,
    preferred_channel, is_phone_verified, is_email_verified
  )
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'first_name', ''),
    coalesce(new.raw_user_meta_data ->> 'last_name', ''),
    '+216',
    null,
    'sms',
    false,
    new.email_confirmed_at is not null
  )
  on conflict (user_id) where user_id is not null do update
  set email = excluded.email,
      is_email_verified = excluded.is_email_verified,
      updated_at = now();

  return new;
end;
$$;

create or replace function public.sync_student_email_verification()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.email_confirmed_at is not null and old.email_confirmed_at is null then
    update public.student_profiles
    set is_email_verified = true, updated_at = now()
    where user_id = new.id;
  end if;
  return new;
end;
$$;

drop trigger if exists sync_student_email_verification on auth.users;

create trigger sync_student_email_verification
after update of email_confirmed_at on auth.users
for each row execute function public.sync_student_email_verification();
